async function main(ctx) {
  const input = ctx.input || {};

  const starshipId = String(input.starshipId ?? ctx.env('STARSHIP_ID') ?? '');
  if (!starshipId) throw new Error('starshipId is required (or STARSHIP_ID must be available in env)');

  const datasetSlug = 'accounts';

  const limitRaw = input.limit;
  const offsetRaw = input.offset;

  const limit = (typeof limitRaw === 'number' && Number.isFinite(limitRaw))
    ? Math.max(0, Math.min(200, Math.trunc(limitRaw)))
    : 10;

  const offset = (typeof offsetRaw === 'number' && Number.isFinite(offsetRaw))
    ? Math.max(0, Math.trunc(offsetRaw))
    : 0;

  const q = (typeof input.search === 'string' && input.search.trim())
    ? input.search.trim()
    : ((typeof input.q === 'string' && input.q.trim()) ? input.q.trim() : '');

  const fields = Array.isArray(input.fields)
    ? input.fields.map(v => (typeof v === 'string' ? v.trim() : '')).filter(Boolean)
    : [];

  const filtersRaw = input.filters;
  const filters = (filtersRaw == null)
    ? undefined
    : ((typeof filtersRaw === 'string' || Array.isArray(filtersRaw) || (typeof filtersRaw === 'object' && !Array.isArray(filtersRaw)))
      ? filtersRaw
      : undefined);

  const expandRefs = Boolean(input.expandRefs);
  const expand = (typeof input.expand === 'string' && input.expand.trim()) ? input.expand.trim() : undefined;

  return {
    listArgs: {
      starshipId,
      datasetSlug,
      limit,
      offset,
      expandRefs,
      expand,
      search: q || undefined,
      filters
    },
    q,
    fields
  };
}

async function main(ctx) {
  const resp = ctx.input || {};
  const body = resp.body;
  if (body && typeof body === 'object' && body.success === true && 'data' in body) return body.data;
  return body ?? resp;
}

function normalizeScalar(v) {
  if (v == null) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'number' || typeof v === 'boolean') return String(v);
  if (typeof v === 'object') {
    if ('label' in v && typeof v.label === 'string') return v.label;
    if ('key' in v && (typeof v.key === 'string' || typeof v.key === 'number')) return String(v.key);
    try { return JSON.stringify(v); } catch { return String(v); }
  }
  return String(v);
}

function matchesQuery(row, qLower, fields) {
  for (const f of fields) {
    const val = normalizeScalar(row?.[f]);
    if (val.toLowerCase().includes(qLower)) return true;
  }
  return false;
}

async function main(ctx) {
  const page = ctx.input || {};
  const prep = ctx.lastOutputOf('prep') || {};

  const q = String(prep.q || '').trim();
  const fields = Array.isArray(prep.fields) ? prep.fields : [];

  // If fields is provided, refine results client-side to matches in those fields.
  // Otherwise, trust server-side search/filter results as-is.
  if (!q || fields.length === 0) return page;

  const qLower = q.toLowerCase();
  const rows = Array.isArray(page.data) ? page.data : [];

  const out = rows.filter(r => matchesQuery(r, qLower, fields));

  return {
    ...page,
    data: out,
    refined: { q, fields, count: out.length }
  };
}
